KG42.register("edges-df0edd1e2497569f2e7a8d5f",{"id":"S-1171a97eef6b23ca","source":"COMP-334f35169e6933ed","type":"links","target":"COMP-443a9bf9853dcd78","evidence_class":"S","scientific_acceptance":false,"relation_scope":"original_occurrence_pair_only","internal_to_parent":false,"paper_ids":["15-multiagent_reverse_auction"],"assertions":[{"id":"15-multiagent_reverse_auction::v141-c-R004::E::v141-c-R004-E001","paper":"15-multiagent_reverse_auction","rule_id":"v141-c-R004","rule_ref":"15-multiagent_reverse_auction::v141-c-R004","record":{"edge_id":"v141-c-R004-E001","source":"bidding.supply","target":"clearing.local","type":"links","constraint_ids":["v141-c-R004-C001"],"evidence_ids":["v141-b-g01-E15","v141-b-g01-E19"]},"evidence_class":"S","provenance_gate":"direct_C_edge_with_constraint_and_source_excerpt","scientific_acceptance":false,"accepted_constraint_ids":["v141-c-R004-C001"],"held_constraint_ids":[],"semantic_review_status":"supported","source":"COMP-334f35169e6933ed","target":"COMP-443a9bf9853dcd78","source_occurrence_id":"15-multiagent_reverse_auction::v141-c-R004::V::bidding.supply","target_occurrence_id":"15-multiagent_reverse_auction::v141-c-R004::V::clearing.local","source_unit_id":"15-multiagent_reverse_auction::v141-a-M01::bidding.supply","target_unit_id":"15-multiagent_reverse_auction::v141-a-M01::clearing.local","omega":{"market_type":"LEM","network_level":null,"jurisdiction":null,"pricing_scope":null,"time_scale":null,"participant_types":[],"trading_stage":"clearing","context_text":"Demand allocation among qualified bidders in the hour-ahead reverse auction. | Hour-ahead allocation of the grid-connected microgrid's lumped demand among qualified DER bidders. | Local DER procurement in the grid-connected microgrid's hour-ahead reverse auction under insufficient supply. | Procurement objective for the microgrid's lumped load in the hour-ahead reverse auction. | Residual demand allocation among qualified bidders in the hour-ahead reverse auction.","unknown_fields":["network_level","jurisdiction","pricing_scope","time_scale","participant_types"],"evidence_ids":["v141-b-g01-E15","v141-b-g01-E19","v141-b-g01-E21"]},"active":true,"source_signature":"e84cccc45bdb2edee6f8eff5e51504437506c4d788d1a2dd7a3cf14d155fa5b6","relation_scope":"original_occurrence_pair_only","internal_to_parent":false,"source_science":{"mechanism_id":"v141-a-M01","source_definition":"Supply-bidding participation requires yellow-pages registration, which implements admission to this microgrid auction. Scope: Supply bidding by available generators in the microgrid's hour-ahead reverse auction. Condition: An available microgrid generator seeks to participate in bidding. The DER aggregator coordinates supply submission by soliciting bids from registered agents. Scope: Solicitation of next-hour DER supply bids in the microgrid reverse auction. Condition: Agents are registered in the yellow pages. The lowered auction-price signal coordinates renewed supply submissions: bidders that remain interested submit the new price, while others withdraw for that hour. Scope: Renewed supply bidding within a particular hourly microgrid auction. Condition: Submitted supply is higher than demand. The bidder submits a supply bid. Scope: Initial bid solicitation for available, registered microgrid generators in Algorithm 1. Condition: DER base price \u003c utility base price. Supply submission is withheld: the bidder drops and does not participate. Scope: Initial bid solicitation for available, registered microgrid generators in Algorithm 1. Condition: The DER base price is not less than the utility base price.","target_definition":"The local allocation process uses the qualified bidder's submitted supply to check whether that bidder can cover all demand. Scope: Hour-ahead allocation of the grid-connected microgrid's lumped demand among qualified DER bidders. The aggregator coordinates local procurement by buying the qualified amount of power from DERs, with the remaining demand purchased from the utility. Scope: Local DER procurement in the grid-connected microgrid's hour-ahead reverse auction under insufficient supply. Condition: Total supply is less than demand and some bidders participate in the auction. Local procurement aims to purchase the required amount of power at the lowest cost. Scope: Procurement objective for the microgrid's lumped load in the hour-ahead reverse auction. The first qualified bidder is supposed to cover the majority of the total demand. Scope: Demand allocation among qualified bidders in the hour-ahead reverse auction. The second qualifying bidder covers the remaining demand. Scope: Residual demand allocation among qualified bidders in the hour-ahead reverse auction. Condition: A supply deficit remains after the first qualified bidder's contribution.","constraints":[{"constraint_id":"v141-c-R004-C001","kind":"procedural","role":"core","statement":"The local allocation process uses the qualified bidder's submitted supply to check whether that bidder can cover all demand. Scope: Hour-ahead allocation of the grid-connected microgrid's lumped demand among qualified DER bidders.","expression":null,"formalization_origin":"not_formalized","template_id":null,"members":["bidding.supply","clearing.local"],"variable_refs":[],"parameter_refs":[],"evidence_ids":["v141-b-g01-E15","v141-b-g01-E19"]}],"evidence":[{"evidence_id":"v141-b-g01-E15","location":{"location_id":"src-1b3df4bc99-p04-c2r3__v141-a-M01-coordination","page":4,"printed_page":null,"section":"IV. Proposed Methodology","anchor_text":"The aggregator manages the communication and the infor- his mation exchange between participants to ","equation_id":null,"figure_id":null,"table_id":null,"image_ref":"pages/page-04.png","occurrence_role":"definition"},"source_text":"The aggregator manages the communication and the information exchange between participants to minimize the cost of the electricity to be purchased for the lumped load. The aggregator agent is the main entity operating the auction process. Its task is to solicit bids form the agents registered to the yellow pages, and to invite them to participate in the auction. The ultimate goal is to purchase the required amount of power with the lowest cost. DERs submit bids to the DER aggregator, declaring the power available to sell and the price for the next hour. Each DER has a generation capacity, marginal cost, and availability."},{"evidence_id":"v141-b-g01-E19","location":{"location_id":"src-1b3df4bc99-p05-c1r3__v141-a-M01-validation","page":5,"printed_page":null,"section":"IV. Proposed Methodology","anchor_text":"to check whether qualiﬁed bidder’s submission is able to cover all demand. The ﬁrst qualiﬁed bidder ","equation_id":null,"figure_id":null,"table_id":null,"image_ref":"pages/page-05.png","occurrence_role":"exception"},"source_text":"One more process is defined to check whether qualified bidder’s submission is able to cover all demand. The first qualified bidder is supposed to cover the majority of the total demand. However, if there is still deficit of supply, the second qualifying bidder covers the remaining amount."}],"omega":{"market_type":"LEM","network_level":null,"jurisdiction":null,"pricing_scope":null,"time_scale":null,"participant_types":[],"trading_stage":"clearing","context_text":"Demand allocation among qualified bidders in the hour-ahead reverse auction. | Hour-ahead allocation of the grid-connected microgrid's lumped demand among qualified DER bidders. | Local DER procurement in the grid-connected microgrid's hour-ahead reverse auction under insufficient supply. | Procurement objective for the microgrid's lumped load in the hour-ahead reverse auction. | Residual demand allocation among qualified bidders in the hour-ahead reverse auction.","unknown_fields":["network_level","jurisdiction","pricing_scope","time_scale","participant_types"],"evidence_ids":["v141-b-g01-E15","v141-b-g01-E19","v141-b-g01-E21"]},"source_record":{"edge_id":"v141-c-R004-E001","source":"bidding.supply","target":"clearing.local","type":"links","constraint_ids":["v141-c-R004-C001"],"evidence_ids":["v141-b-g01-E15","v141-b-g01-E19"]},"paper_scope_note":"Registration, auction invitation, bid, eligibility, and final power command are checked separately; the utility base price differs from the DER private base price; the general single-winner and two-winner cases are not combined into the same condition."}}],"assertion_ids":["15-multiagent_reverse_auction::v141-c-R004::E::v141-c-R004-E001"]});
